/*
 * A362556  Number of distinct n-digit suffixes generated by iteratively
 *          multiplying an integer by 8, where the initial integer is 1.
 * https://oeis.org/A362556
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) = 6*a(n-1) - 5*a(n-2) + a(n-3) - 6*a(n-4) + 5*a(n-5) with
 *            initial values a(1)=5, a(2)=21, a(3)=101, a(4)=502, a(5)=2502
 * Range:     u8 n <= 3, u16 n <= 7, u32 n <= 13, u64 n <= 27, u128 n <= 55,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    if (n == 1) return (seq_t)5;
    if (n == 2) return (seq_t)21;
    if (n == 3) return (seq_t)101;
    if (n == 4) return (seq_t)502;
    if (n == 5) return (seq_t)2502;

    seq_t a1 = (seq_t)5;
    seq_t a2 = (seq_t)21;
    seq_t a3 = (seq_t)101;
    seq_t a4 = (seq_t)502;
    seq_t a5 = (seq_t)2502;

    for (idx_t i = 6; i <= n; ++i) {
        seq_t next = 6*a5 - 5*a4 + a3 - 6*a2 + 5*a1;
        a1 = a2;
        a2 = a3;
        a3 = a4;
        a4 = a5;
        a5 = next;
    }
    return a5;
}
